+
+::deep .settings-sidebar li {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    padding: 0.75rem 1.5rem;
+    cursor: pointer;
+    transition: background 0.2s, border-left 0.2s;
+    border-left: 3px solid transparent;
+    font-size: 0.95rem;
+}
+
+::deep .settings-sidebar li:hover {
+    background: #e9ecef;
+}
+
+::deep .settings-sidebar li.active {
+    background: #e3f2fd;
+    border-left-color: #1976d2;
+    font-weight: 600;
+    color: #1976d2;
+}
+
+::deep .sidebar-icon {
+    font-size: 1.2rem;
+}
+
+/* Main Content */
+.settings-content {
+    flex: 1;
+    padding: 2rem;
+    max-width: 800px;
+}
+
+/* Shared Section Styles */
+::deep .settings-section h2 {
+    margin-top: 0;
+    margin-bottom: 1.5rem;
+    font-size: 1.5rem;
+    color: #333;
+}
+
+::deep .settings-section h3 {
+    margin-top: 1.5rem;
+    margin-bottom: 0.75rem;
+    font-size: 1.1rem;
+    color: #555;
+}
+
+/* Form Elements */
+::deep .form-group {
+    margin-bottom: 1.25rem;
+}
+
+::deep .form-group label {
+    display: block;
+    margin-bottom: 0.4rem;
+    font-weight: 500;
+    color: #444;
+}
+
+::deep .form-group input[type="text"],
+::deep .form-group input[type="email"],
+::deep .form-group input[type="password"],
+::deep .form-group textarea,
+::deep .form-group select {
+    width: 100%;
+    padding: 0.5rem 0.75rem;
+    border: 1px solid #ccc;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    box-sizing: border-box;
+}
+
+::deep .form-group textarea {
+    resize: vertical;
+}
+
+::deep .form-group select {
+    max-width: 300px;
+}
+
+/* Buttons */
+::deep .form-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.5rem;
+}
+
+::deep .btn-primary {
+    background: #1976d2;
+    color: white;
+    border: none;
+    padding: 0.6rem 1.25rem;
+    border-radius: 4px;
+    cursor: pointer;
+    font-size: 0.9rem;
+    font-weight: 500;
+}
+
+::deep .btn-primary:hover {
+    background: #1565c0;
+}
+
+::deep .btn-secondary {
+    background: #f5f5f5;
+    color: #333;
+    border: 1px solid #ccc;
+    padding: 0.6rem 1.25rem;
+    border-radius: 4px;
+    cursor: pointer;
+    font-size: 0.9rem;
+}
+
+::deep .btn-secondary:hover {
+    background: #e0e0e0;
+}
+
+::deep .btn-danger {
+    background: #d32f2f;
+    color: white;
+    border: none;
+    padding: 0.6rem 1.25rem;
+    border-radius: 4px;
+    cursor: pointer;
+    font-size: 0.9rem;
+}
+
+::deep .btn-danger:hover {
+    background: #c62828;
+}
+
+::deep .btn-small {
+    padding: 0.3rem 0.75rem;
+    font-size: 0.8rem;
+}
+
+/* Toast */
+::deep .toast {
+    margin-top: 1rem;
+    padding: 0.75rem 1rem;
+    border-radius: 4px;
+    font-size: 0.9rem;
+    animation: fadeIn 0.3s ease-in;
+}
+
+::deep .toast.success {
+    background: #e8f5e9;
+    color: #2e7d32;
+    border: 1px solid #a5d6a7;
+}
+
+@keyframes fadeIn {
+    from { opacity: 0; transform: translateY(-10px); }
+    to { opacity: 1; transform: translateY(0); }
+}
+
+/* Toggle Items */
+::deep .toggle-group {
+    display: flex;
+    flex-direction: column;
+    gap: 0.75rem;
+}
+
+::deep .toggle-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    cursor: pointer;
+}
+
+::deep .toggle-item input[type="checkbox"] {
+    width: 1.1rem;
+    height: 1.1rem;
+}
+
+/* Channel List */
+::deep .channel-list {
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+    padding-left: 0.5rem;
+}
+
+::deep .channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    cursor: pointer;
+}
+
+/* Avatar */
+::deep .avatar-preview {
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+    margin-bottom: 1.5rem;
+    padding: 1rem;
+    background: #f5f5f5;
+    border-radius: 8px;
+}
+
+::deep .avatar-image {
+    width: 80px;
+    height: 80px;
+    border-radius: 50%;
+    object-fit: cover;
+    border: 2px solid #ddd;
+}
+
+::deep .avatar-url {
+    font-size: 0.85rem;
+    color: #666;
+    word-break: break-all;
+}
+
+/* Expandable Panel */
+::deep .expandable-panel {
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    margin-bottom: 1.5rem;
+}
+
+::deep .panel-header {
+    width: 100%;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 0.75rem 1rem;
+    background: #fafafa;
+    border: none;
+    cursor: pointer;
+    font-size: 1rem;
+    font-weight: 500;
+    border-radius: 6px;
+}
+
+::deep .panel-header:hover {
+    background: #f0f0f0;
+}
+
+::deep .panel-content {
+    padding: 1rem;
+    border-top: 1px solid #e0e0e0;
+}
+
+/* Security Items */
+::deep .security-item {
+    margin-bottom: 1.5rem;
+}
+
+::deep .status-row {
+    display: flex;
+    align-items: center;
+    gap: 1.5rem;
+}
+
+::deep .status-indicator {
+    font-weight: 500;
+    padding: 0.3rem 0.75rem;
+    border-radius: 12px;
+    font-size: 0.85rem;
+}
+
+::deep .status-indicator.enabled {
+    background: #e8f5e9;
+    color: #2e7d32;
+}
+
+::deep .status-indicator.disabled {
+    background: #fbe9e7;
+    color: #d32f2f;
+}
+
+::deep .info-text {
+    font-size: 0.85rem;
+    color: #666;
+    margin-top: 0.5rem;
+}
+
+/* Sessions Table */
+::deep .sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    margin-top: 0.75rem;
+}
+
+::deep .sessions-table th,
+::deep .sessions-table td {
+    padding: 0.6rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+::deep .sessions-table th {
+    background: #f5f5f5;
+    font-weight: 600;
+    font-size: 0.85rem;
+    color: #555;
+}
+
+::deep .current-badge {
+    font-size: 0.8rem;
+    color: #1976d2;
+    font-weight: 500;
+}
+
+/* Error Message */
+::deep .error-message {
+    color: #d32f2f;
+    font-size: 0.85rem;
+    margin-bottom: 0.75rem;
+}
+
+/* Modal */
+::deep .modal-overlay {
+    position: fixed;
+    top: 0;
+    left: 0;
+    right: 0;
+    bottom: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+::deep .modal-dialog {
+    background: white;
+    padding: 1.5rem;
+    border-radius: 8px;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
+}
+
+::deep .modal-dialog h4 {
+    margin-top: 0;
+    margin-bottom: 0.75rem;
+}
+
+::deep .modal-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.25rem;
+    justify-content: flex-end;
+}
+
+/* Radio Group */
+::deep .radio-group {
+    display: flex;
+    gap: 1.5rem;
+    margin-top: 0.25rem;
+}
+
+::deep .radio-item {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+/* Preview Area */
+::deep .preview-area {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    transition: all 0.3s ease;
+}
+
+::deep .preview-area.theme-light {
+    background: #ffffff;
+    color: #333;
+}
+
+::deep .preview-area.theme-dark {
+    background: #1e1e1e;
+    color: #e0e0e0;
+}
+
+::deep .preview-area.theme-system {
+    background: #f5f5f5;
+    color: #333;
+}
+
+::deep .preview-area.font-small {
+    font-size: 0.8rem;
+}
+
+::deep .preview-area.font-medium {
+    font-size: 1rem;
+}
+
+::deep .preview-area.font-large {
+    font-size: 1.2rem;
+}
+
+::deep .preview-area.compact {
+    padding: 0.75rem;
+    line-height: 1.2;
+}
+
+::deep .preview-card {
+    margin-top: 0.75rem;
+    padding: 0.75rem;
+    border: 1px solid currentColor;
+    border-radius: 4px;
+    opacity: 0.8;
+}
+
+::deep .preview-text {
+    margin: 0.5rem 0;
+}
+

